// The purpose of this layer is to manage communication with the GPT API.

namespace Infrastructure.GPT
{
    using System.Net.Http;
    using System.Threading.Tasks;
    using Newtonsoft.Json;

    // HTTP Client Manager for API Communication
    public class GPTApiClient
    {
        private readonly HttpClient _httpClient;
        private readonly string _apiKey;

        public GPTApiClient(HttpClient httpClient, string apiKey)
        {
            _httpClient = httpClient;
            _apiKey = apiKey;
        }

        // Core method to send requests to the GPT API
        public async Task<string> SendRequestAsync(string endpoint, object payload)
        {
            var request = new HttpRequestMessage(HttpMethod.Post, endpoint);
            request.Headers.Add("Authorization", $"Bearer {_apiKey}");

            var jsonPayload = JsonConvert.SerializeObject(payload);
            request.Content = new StringContent(jsonPayload, System.Text.Encoding.UTF8, "application/json");

            var response = await _httpClient.SendAsync(request);

            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException($"GPT API call failed with status code {response.StatusCode}");
            }

            return await response.Content.ReadAsStringAsync();
        }
    }

    // Model classes for GPT API interaction
    public class GPTRequest
    {
        public string Model { get; set; }
        public string Prompt { get; set; }
        public int MaxTokens { get; set; }
        public double Temperature { get; set; }
        public double TopP { get; set; }

        public GPTRequest(string model, string prompt, int maxTokens, double temperature, double topP)
        {
            Model = model;
            Prompt = prompt;
            MaxTokens = maxTokens;
            Temperature = temperature;
            TopP = topP;
        }
    }

    public class GPTResponse
    {
        public string Id { get; set; }
        public string Object { get; set; }
        public int Created { get; set; }
        public string Model { get; set; }
        public Choice[] Choices { get; set; }

        public class Choice
        {
            public string Text { get; set; }
            public int Index { get; set; }
            public string FinishReason { get; set; }
        }
    }

    // Service class to wrap API-specific methods
    public class GPTService
    {
        private readonly GPTApiClient _apiClient;

        public GPTService(GPTApiClient apiClient)
        {
            _apiClient = apiClient;
        }

        // Method to execute a text completion
        public async Task<string> GenerateTextAsync(string model, string prompt, int maxTokens = 100, double temperature = 0.7, double topP = 1.0)
        {
            var request = new GPTRequest(model, prompt, maxTokens, temperature, topP);
            var responseJson = await _apiClient.SendRequestAsync("https://api.openai.com/v1/completions", request);

            var response = JsonConvert.DeserializeObject<GPTResponse>(responseJson);
            return response?.Choices?[0]?.Text ?? string.Empty;
        }

        // Method to train a custom model (fine-tuning)
        public async Task<string> FineTuneModelAsync(object fineTunePayload)
        {
            return await _apiClient.SendRequestAsync("https://api.openai.com/v1/fine-tunes", fineTunePayload);
        }

        // Method to retrieve a list of available models
        public async Task<string> ListModelsAsync()
        {
            return await _apiClient.SendRequestAsync("https://api.openai.com/v1/models", null);
        }
    }
}"}

