namespace Infrastructure.GPT
{
    using System.Threading.Tasks;

    public interface IGPTApi
    {
        /// <summary>
        /// Generates a text completion based on a prompt.
        /// </summary>
        /// <param name="model">The model to use for completion.</param>
        /// <param name="prompt">The input prompt for text generation.</param>
        /// <param name="maxTokens">Maximum tokens to generate.</param>
        /// <param name="temperature">Sampling temperature.</param>
        /// <param name="topP">Probability mass for nucleus sampling.</param>
        /// <returns>The generated text.</returns>
        Task<string> GenerateTextAsync(string model, string prompt, int maxTokens = 100, double temperature = 0.7, double topP = 1.0);

        /// <summary>
        /// Triggers fine-tuning of a custom model using provided training data.
        /// </summary>
        /// <param name="fineTunePayload">The payload containing training data and parameters.</param>
        /// <returns>The fine-tuning job ID or status.</returns>
        Task<string> FineTuneModelAsync(object fineTunePayload);

        /// <summary>
        /// Retrieves a list of all available models.
        /// </summary>
        /// <returns>A list of available model IDs or metadata.</returns>
        Task<string> ListModelsAsync();

        /// <summary>
        /// Retrieves embeddings for a given input.
        /// </summary>
        /// <param name="model">The model to use for generating embeddings.</param>
        /// <param name="input">The input text for which embeddings are needed.</param>
        /// <returns>The embedding vector for the input text.</returns>
        Task<string> GetEmbeddingsAsync(string model, string input);

        /// <summary>
        /// Generates edits for a provided input and instruction.
        /// </summary>
        /// <param name="model">The model to use for generating edits.</param>
        /// <param name="input">The input text to edit.</param>
        /// <param name="instruction">The instruction to guide the edits.</param>
        /// <returns>The edited text.</returns>
        Task<string> GenerateEditsAsync(string model, string input, string instruction);

        /// <summary>
        /// Analyzes content for policy violations.
        /// </summary>
        /// <param name="input">The content to analyze.</param>
        /// <returns>The moderation results.</returns>
        Task<string> ModerateContentAsync(string input);

        /// <summary>
        /// Uploads a file for fine-tuning or other purposes.
        /// </summary>
        /// <param name="filePath">The path of the file to upload.</param>
        /// <returns>The file ID or upload status.</returns>
        Task<string> UploadFileAsync(string filePath);

        /// <summary>
        /// Lists all uploaded files.
        /// </summary>
        /// <returns>A list of uploaded files.</returns>
        Task<string> ListUploadedFilesAsync();

        /// <summary>
        /// Deletes a specific file by ID.
        /// </summary>
        /// <param name="fileId">The ID of the file to delete.</param>
        /// <returns>The status of the deletion operation.</returns>
        Task<string> DeleteFileAsync(string fileId);

        /// <summary>
        /// Transcribes audio to text.
        /// </summary>
        /// <param name="filePath">The path to the audio file.</param>
        /// <returns>The transcribed text.</returns>
        Task<string> TranscribeAudioAsync(string filePath);

        /// <summary>
        /// Translates audio to English.
        /// </summary>
        /// <param name="filePath">The path to the audio file.</param>
        /// <returns>The translated text.</returns>
        Task<string> TranslateAudioAsync(string filePath);
    }
}"}

