namespace Infrastructure.GPT
{
    using System;
    using System.IO;
    using System.Net.Http;
    using System.Threading.Tasks;
    using Newtonsoft.Json;

    public class GPTApiClient : IGPTApi
    {
        private readonly HttpClient _httpClient;
        private readonly string _apiKey;

        public GPTApiClient(HttpClient httpClient, string apiKey)
        {
            _httpClient = httpClient;
            _apiKey = apiKey;
        }

        private async Task<string> SendRequestAsync(string endpoint, HttpMethod method, object payload = null)
        {
            var request = new HttpRequestMessage(method, endpoint);
            request.Headers.Add("Authorization", $"Bearer {_apiKey}");

            if (payload != null)
            {
                var jsonPayload = JsonConvert.SerializeObject(payload);
                request.Content = new StringContent(jsonPayload, System.Text.Encoding.UTF8, "application/json");
            }

            var response = await _httpClient.SendAsync(request);

            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException($"API call failed with status code {response.StatusCode}: {await response.Content.ReadAsStringAsync()}");
            }

            return await response.Content.ReadAsStringAsync();
        }

        public async Task<string> GenerateTextAsync(string model, string prompt, int maxTokens = 100, double temperature = 0.7, double topP = 1.0)
        {
            var payload = new
            {
                model,
                prompt,
                max_tokens = maxTokens,
                temperature,
                top_p = topP
            };

            var endpoint = "https://api.openai.com/v1/completions";
            return await SendRequestAsync(endpoint, HttpMethod.Post, payload);
        }

        public async Task<string> FineTuneModelAsync(object fineTunePayload)
        {
            var endpoint = "https://api.openai.com/v1/fine-tunes";
            return await SendRequestAsync(endpoint, HttpMethod.Post, fineTunePayload);
        }

        public async Task<string> ListModelsAsync()
        {
            var endpoint = "https://api.openai.com/v1/models";
            return await SendRequestAsync(endpoint, HttpMethod.Get);
        }

        public async Task<string> GetEmbeddingsAsync(string model, string input)
        {
            var payload = new { model, input };
            var endpoint = "https://api.openai.com/v1/embeddings";
            return await SendRequestAsync(endpoint, HttpMethod.Post, payload);
        }

        public async Task<string> GenerateEditsAsync(string model, string input, string instruction)
        {
            var payload = new
            {
                model,
                input,
                instruction
            };

            var endpoint = "https://api.openai.com/v1/edits";
            return await SendRequestAsync(endpoint, HttpMethod.Post, payload);
        }

        public async Task<string> ModerateContentAsync(string input)
        {
            var payload = new { input };
            var endpoint = "https://api.openai.com/v1/moderations";
            return await SendRequestAsync(endpoint, HttpMethod.Post, payload);
        }

        public async Task<string> UploadFileAsync(string filePath)
        {
            var endpoint = "https://api.openai.com/v1/files";
            using var fileStream = File.OpenRead(filePath);
            var content = new MultipartFormDataContent
            {
                { new StreamContent(fileStream), "file", Path.GetFileName(filePath) }
            };

            var request = new HttpRequestMessage(HttpMethod.Post, endpoint)
            {
                Headers = { { "Authorization", $"Bearer {_apiKey}" } },
                Content = content
            };

            var response = await _httpClient.SendAsync(request);

            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException($"File upload failed: {await response.Content.ReadAsStringAsync()}");
            }

            return await response.Content.ReadAsStringAsync();
        }

        public async Task<string> ListUploadedFilesAsync()
        {
            var endpoint = "https://api.openai.com/v1/files";
            return await SendRequestAsync(endpoint, HttpMethod.Get);
        }

        public async Task<string> DeleteFileAsync(string fileId)
        {
            var endpoint = $"https://api.openai.com/v1/files/{fileId}";
            return await SendRequestAsync(endpoint, HttpMethod.Delete);
        }

        public async Task<string> TranscribeAudioAsync(string filePath)
        {
            var endpoint = "https://api.openai.com/v1/audio/transcriptions";
            using var fileStream = File.OpenRead(filePath);
            var content = new MultipartFormDataContent
            {
                { new StreamContent(fileStream), "file", Path.GetFileName(filePath) }
            };

            var request = new HttpRequestMessage(HttpMethod.Post, endpoint)
            {
                Headers = { { "Authorization", $"Bearer {_apiKey}" } },
                Content = content
            };

            var response = await _httpClient.SendAsync(request);

            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException($"Audio transcription failed: {await response.Content.ReadAsStringAsync()}");
            }

            return await response.Content.ReadAsStringAsync();
        }

        public async Task<string> TranslateAudioAsync(string filePath)
        {
            var endpoint = "https://api.openai.com/v1/audio/translations";
            using var fileStream = File.OpenRead(filePath);
            var content = new MultipartFormDataContent
            {
                { new StreamContent(fileStream), "file", Path.GetFileName(filePath) }
            };

            var request = new HttpRequestMessage(HttpMethod.Post, endpoint)
            {
                Headers = { { "Authorization", $"Bearer {_apiKey}" } },
                Content = content
            };

            var response = await _httpClient.SendAsync(request);

            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException($"Audio translation failed: {await response.Content.ReadAsStringAsync()}");
            }

            return await response.Content.ReadAsStringAsync();
        }
    }
}"}

